import React, { useRef } from 'react';
import { shaderMaterial } from '@react-three/drei';
import { extend, useFrame } from '@react-three/fiber';
import * as THREE from 'three';
const WaveMaterial = shaderMaterial(
  { uTime: 0, uColor: new THREE.Color('#38bdf8') },
  `varying vec2 vUv; void main() { vUv = uv; vec3 p = position; p.z += sin(p.x * 4.0 + uTime) * 0.2; gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0); }`,
  `uniform vec3 uColor; varying vec2 vUv; void main() { gl_FragColor = vec4(uColor * (0.8 + 0.2 * vUv.y), 1.0); }`
);
extend({ WaveMaterial });

import React, { useRef, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';
const TEMP_VEC = new THREE.Vector3();
export function CleanAnimation() {
  const meshRef = useRef<THREE.Mesh>(null);
  const { invalidate } = useThree();
  useFrame((state, delta) => {
    if (!meshRef.current) return;
    TEMP_VEC.set(Math.sin(state.clock.elapsedTime), 0, 0);
    meshRef.current.position.copy(TEMP_VEC);
    invalidate();
  });
  return <mesh ref={meshRef}><boxGeometry args={[1, 1, 1]} /><meshBasicMaterial color='#10b981' /></mesh>;
}

import React, { useEffect } from 'react';
import { useThree } from '@react-three/fiber';
export function ResponsiveCameraRig() {
  const { camera, size } = useThree();
  useEffect(() => {
    const isNarrow = size.width < 768;
    if ('fov' in camera) {
      camera.fov = isNarrow ? 70 : 50;
      camera.position.z = isNarrow ? 7 : 5;
      camera.updateProjectionMatrix();
    }
  }, [size.width, camera]);
  return null;
}

